import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import AppShell from './AppShell';
import { getHistory } from '../services/api';

export default function Dashboard() {
  const navigate = useNavigate();
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const storedUser = localStorage.getItem('user');
  const user = storedUser ? JSON.parse(storedUser) : null;
  const profile = user?.profile || {};

  useEffect(() => {
    let isMounted = true;

    const fetchHistory = async () => {
      setLoading(true);
      setError('');
      try {
        const response = await getHistory();
        if (isMounted) {
          setHistory(Array.isArray(response) ? response : []);
        }
      } catch (fetchError) {
        if (fetchError.message === 'Missing authentication token') {
          navigate('/login');
          return;
        }
        if (isMounted) {
          setError(fetchError.message || 'Failed to fetch data');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    fetchHistory();
    return () => {
      isMounted = false;
    };
  }, [navigate]);

  const summary = useMemo(() => {
    const latest = history[0];
    const avg = (key) =>
      history.length
        ? history.reduce((sum, item) => sum + Number(item.input_data?.[key] || 0), 0) / history.length
        : 0;

    return {
      lastScore: latest ? Number(latest.score).toFixed(1) : '--',
      avgSleep: avg('sleep') ? `${avg('sleep').toFixed(1)}h` : '0h',
      avgWater: avg('water') ? `${avg('water').toFixed(1)}L` : '0L',
      avgCalories: avg('calories') ? `${Math.round(avg('calories'))}` : '0',
      streakDays: new Set(history.slice(0, 7).map((item) => new Date(item.created_at).toDateString())).size,
    };
  }, [history]);

  return (
    <AppShell
      title={`Welcome back, ${user?.name || 'User'}`}
      subtitle="Here is your personalized health command center with hydration, food, goals, and prediction progress."
    >
      {loading ? <div className="empty-state">Loading...</div> : null}
      {!loading && error ? <div className="empty-state">{error || 'Failed to fetch data'}</div> : null}

      {!loading && !error ? (
        <>
          <section className="hero-dashboard">
            <div className="hero-dashboard-card primary">
              <span className="eyebrow">Current health score</span>
              <strong>{summary.lastScore}</strong>
              <p>Latest ML prediction from your sleep, water, exercise, and calorie inputs.</p>
            </div>
            <div className="hero-dashboard-card">
              <span className="eyebrow">Water goal</span>
              <strong>{profile.daily_water_goal || '3'}L</strong>
              <p>Daily hydration target from your onboarding profile.</p>
            </div>
            <div className="hero-dashboard-card">
              <span className="eyebrow">Food profile</span>
              <strong>{profile.food_preference || 'Balanced'}</strong>
              <p>{profile.food_notes || 'No food notes added yet.'}</p>
            </div>
          </section>

          <div className="stats-grid advanced">
            <div className="stat-card">
              <div className="card-icon icon-orange">SC</div>
              <p className="stat-value">{summary.lastScore}</p>
              <div className="stat-label">Last score</div>
            </div>
            <div className="stat-card">
              <div className="card-icon icon-teal">SL</div>
              <p className="stat-value">{summary.avgSleep}</p>
              <div className="stat-label">Avg. sleep</div>
            </div>
            <div className="stat-card">
              <div className="card-icon icon-blue">WA</div>
              <p className="stat-value">{summary.avgWater}</p>
              <div className="stat-label">Avg. water</div>
            </div>
            <div className="stat-card">
              <div className="card-icon icon-purple">CA</div>
              <p className="stat-value">{summary.avgCalories}</p>
              <div className="stat-label">Avg. calories</div>
            </div>
          </div>

          <section className="dashboard-grid">
            <div className="panel-card feature-panel">
              <div className="panel-head">
                <h3>Quick Actions</h3>
                <span className="top-pill">Streak: {summary.streakDays} days</span>
              </div>
              <div className="action-grid advanced">
                <button type="button" className="action-card" onClick={() => navigate('/predict')}>
                  <div className="card-icon icon-teal">PR</div>
                  <h3>Predict Health Score</h3>
                  <p>Run a fresh ML prediction from your daily metrics.</p>
                  <span className="card-arrow">Go</span>
                </button>
                <button type="button" className="action-card" onClick={() => navigate('/history')}>
                  <div className="card-icon icon-purple">HI</div>
                  <h3>View History</h3>
                  <p>Review previous scores, hydration, sleep, and calorie trends.</p>
                  <span className="card-arrow">Go</span>
                </button>
                <button type="button" className="action-card" onClick={() => navigate('/chat')}>
                  <div className="card-icon icon-orange">AI</div>
                  <h3>Open Chatbot</h3>
                  <p>Ask about food, water intake, exercise, or sleep improvement.</p>
                  <span className="card-arrow">Go</span>
                </button>
              </div>
            </div>

            <div className="panel-card profile-panel">
              <h3>Your Health Profile</h3>
              <div className="mini-grid">
                <div className="mini-card"><span className="hint">Goal</span><strong>{profile.goal || 'Stay Fit'}</strong></div>
                <div className="mini-card"><span className="hint">Activity</span><strong>{profile.activity_level || 'Moderate'}</strong></div>
                <div className="mini-card"><span className="hint">Height</span><strong>{profile.height || '--'} cm</strong></div>
                <div className="mini-card"><span className="hint">Weight</span><strong>{profile.weight || '--'} kg</strong></div>
              </div>
            </div>
          </section>
        </>
      ) : null}
    </AppShell>
  );
}
